using System;using System.IO;using System.Text.Json;using System.Collections.Generic;using Emberfall;
class Program{static float idleLength;
static object Sample(int index,float time,float phase,float speed,float progress,string scenario){var x=BlenderPilotPosePolicy.Layers(time,idleLength,phase,speed,progress);return new{index,time,phase,speed,progress,basic=progress<1,idle=x.IdleTime,move=x.MoveTime,speedWeight=x.SpeedWeight,upperWeight=x.UpperWeight,scenario};}
static void Main(string[] args){string dir=args[0];idleLength=float.Parse(args[1],System.Globalization.CultureInfo.InvariantCulture);var doc=JsonDocument.Parse(File.ReadAllText(dir+"/motion.json"));var frames=doc.RootElement.GetProperty("frames");var samples=new List<object>();foreach(var f in frames.EnumerateArray())samples.Add(Sample(f.GetProperty("index").GetInt32(),f.GetProperty("time").GetSingle(),f.GetProperty("phase").GetSingle(),f.GetProperty("speed").GetSingle(),f.GetProperty("progress").GetSingle(),"continuous-forward"));
File.WriteAllText(dir+"/candidate-samples.json",JsonSerializer.Serialize(new{samples}));
var loc=new LocomotionPoseState();var stop=new List<object>();const float dt=1f/120;for(int tick=0;tick<720;tick++){float t=tick*dt;bool walking=t<1.4f||t>=2.4f;loc.Advance(0,walking?6*dt:0,dt,6,walking,false,0);if(tick%5==0)stop.Add(Sample(tick/5,t,loc.Phase,loc.Speed,frames[tick/5].GetProperty("progress").GetSingle(),"stop1.4-restart2.4"));}File.WriteAllText(dir+"/candidate-stop-samples.json",JsonSerializer.Serialize(new{samples=stop}));Console.WriteLine("Exported "+samples.Count+" actual policy baseline inputs and "+stop.Count+" actual locomotion stop/restart inputs");}}
